"""Editorial studio pages. Store listings stay authoritative for builds and pricing."""
from pathlib import Path
import json, html, re

R = Path(__file__).resolve().parents[1]
E = html.escape
NAV = '<nav class="studio-nav" aria-label="Main navigation"><a href="/play/">Play</a><a href="/create/">Create</a><a href="/worlds/">Worlds & media</a><a href="/about/">Studio</a><a href="/help/">Support</a></nav>'
FOOTER = '<a href="/play/">Play</a><a href="/create/">Create</a><a href="/worlds/">Worlds & media</a><a href="/desktop-buddy/">Desktop Buddy</a><a href="/about/">Studio</a><a href="/press/">Press & contact</a><a href="/help/">Support</a><a href="/privacy/">Privacy</a><a href="/delete-account/">Account deletion</a><p>Drunk Yeti Studio</p>'

def path(p):
    return f'/{p["section"]}/{p["slug"]}/'

def asset(c):
    return '/' + c['image'].removeprefix('./')

def card(p, catalog):
    c = catalog[p['catalogSlug']]
    return f'<article class="spotlight-card"><a href="{path(p)}"><img src="{asset(c)}" alt="{E(p["name"])} cover artwork" width="315" height="250" loading="lazy"><div><span class="eyebrow">{E(p["section"])}</span><h3>{E(p["name"])}</h3><p>{E(p["tagline"])}</p><span class="card-link">Explore the project →</span></div></a></article>'

def browser_cards(products, catalog):
    return '<div class="browser-grid">' + ''.join(
        f'<article class="browser-card"><span class="eyebrow">BROWSER EXPERIENCE</span><h3>{E(p["browserName"])}</h3><p>{E(p["browserNote"])}</p><a class="button ink" href="{E(p["browser"],quote=True)}" target="_blank" rel="noopener noreferrer">Play in browser ↗<span class="sr-only"> — {E(p["browserName"])} (opens a new tab)</span></a><a class="card-link" href="{path(p)}">About {E(p["name"])} →</a></article>'
        for p in products if p.get('browser')) + '</div>'

def build(page, write, cards):
    data = json.loads((R/'studio-content.json').read_text())
    products = data['products']
    catalog = {c['url'].rstrip('/').split('/')[-1]: c for c in cards}
    for p in products:
        if p.get('releaseUrl'):
            catalog[p['catalogSlug']] = {'url': p['releaseUrl'], 'image': p['image'], 'title': p['name']}
    lookup = {p['slug']: p for p in products}
    urls = []
    for p in products:
        c = catalog[p['catalogSlug']]
        url = path(p)
        media = R/'assets/studio'/f'{p["catalogSlug"]}.webp'
        gallery = ''
        if media.exists() and not p.get("releaseUrl"):
            sizes=json.loads((R/'assets/studio/sources.json').read_text())
            dims=next(x for x in sizes if x['slug']==p['catalogSlug'])
            gallery = f'<figure class="project-gallery"><img src="/assets/studio/{p["catalogSlug"]}.webp" alt="{E(p["name"])} — image from the official release gallery" width="{dims["width"]}" height="{dims["height"]}" loading="lazy"><figcaption>From the official release gallery. Images may show an earlier build; see release notes for current details.</figcaption></figure>'
        browser = ''
        if p.get('browser'):
            browser = f'<section class="callout"><h2>{E(p["browserName"])}</h2><p>{E(p["browserNote"])}</p><a class="button ink" href="{p["browser"]}" target="_blank" rel="noopener noreferrer">Play in browser ↗<span class="sr-only"> (opens a new tab)</span></a></section>'
        facts = p.get('releaseFacts')
        release = ''
        if facts:
            video = f'<a class="button ink" href="{E(facts["video"],quote=True)}" target="_blank" rel="noopener noreferrer">Watch official gameplay / demo ↗<span class="sr-only"> (opens a new tab)</span></a>' if facts.get('video') else ''
            release = f'<section class="release-details" aria-labelledby="release-details-title"><h2 id="release-details-title">Before you start</h2><dl><dt>Current listing</dt><dd>{E(facts["status"])}</dd><dt>Platforms & requirements</dt><dd>{E(facts["requirements"])}</dd><dt>Release notes</dt><dd>{E(facts["notes"])}</dd></dl>{video}<p class="release-source">Checked {E(facts["checked"])} against the <a href="{E(facts["source"],quote=True)}">official release listing</a>. See the listing for newer builds and full release details.</p></section>'
        features = ''.join(f'<section><h2>{E(h)}</h2><p>{E(t)}</p></section>' for h,t in p['features'])
        related = ''.join(card(lookup[x],catalog) for x in p['related'])
        body = f'<div class="project-lead"><div><p class="project-tagline">{E(p["tagline"])}</p><p>{E(p["intro"])}</p><a class="button ink" href="{c["url"]}">{E(p.get("releaseLabel", "Official release & downloads ↗"))}</a></div><img src="{asset(c)}" width="630" height="500" alt="{E(p["name"])} cover artwork"></div>{browser}<div class="feature-columns">{features}</div>{gallery}<section class="callout"><h2>Choose your edition</h2><p>{E(p["edition"])}</p><p><a href="{c["url"]}">{E(p.get("releaseLabel", "See current downloads and release details ↗"))}</a> · <a href="/help/">Get support</a></p></section><section class="related"><h2>Keep exploring</h2><div class="spotlight-grid">{related}</div></section>'
        body = body.replace('<section class="related">',release+'<section class="related">')
        schema = {'@context':'https://schema.org','@graph':[
            {'@type':'WebPage','name':p['name'],'description':p['description'],'url':'https://www.drunkyetistudio.com'+url,'about':{'@type':'CreativeWork','name':p['name'],'url':c['url'],'creator':{'@type':'Organization','name':'Drunk Yeti Studio'}}},
            {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://www.drunkyetistudio.com/'},{'@type':'ListItem','position':2,'name':p['section'].title(),'item':'https://www.drunkyetistudio.com/'+p['section']+'/'},{'@type':'ListItem','position':3,'name':p['name'],'item':'https://www.drunkyetistudio.com'+url}]}]}
        write(url.strip('/')+'/index.html', page(url,p['name'],p['description'],body,schema));urls.append(url)

    def publish(slug,title,description,body,intro=None):
        write(slug+'/index.html',page('/'+slug+'/',title,description,body,intro=intro));urls.append('/'+slug+'/')

    play_intro = '<section><h2>A quick game. A longer adventure. Your call.</h2><p>Start in your browser or find a downloadable game for your next session. Explore party arenas, downhill adventures, card games, and original worlds. Each project page connects you to its official release, with current editions and requirements.</p></section>'
    play = play_intro+'<section class="wide"><h2>Play on our game servers</h2><p>These experiences open in their own tabs. Give game files time to load; content and controls can differ from the downloadable editions.</p>'+browser_cards(products,catalog)+'</section><section class="wide"><h2>Featured games</h2><div class="spotlight-grid">'+''.join(card(p,catalog) for p in products if p['section']=='games')+'</div></section><section class="callout"><h2>More ways to play</h2><p><a href="/games/">Browse every game</a> · <a href="/mods/">Explore mods</a> · <a href="https://store.steampowered.com/curator/45875400">Find us on Steam ↗</a></p><p>For membership access, check the current Included or Integration planned status on <a href="/account/#frostpass">Yeti Frostpass</a>. Store editions and browser builds can include different content.</p></section>'
    publish('play','Find your next game','Play Drunk Yeti browser games and discover original arena, downhill, snowboarding, and card-game adventures.',play)

    def links(slugs):
        return '<ul class="tool-links">'+''.join(f'<li><a href="{catalog[s]["url"]}">{E(catalog[s]["title"])} ↗</a></li>' for s in slugs)+'</ul>'
    makers = [c for c in cards if c['category']=='Tools' and 'Maker' in c['title'] and c['title'] not in ('eBook Maker','Pattern Maker','BrushMakerPro')]
    create = '<section><h2>Make the thing you want to see in the world.</h2><p>Our software spans game creation, visual art, music, motion, and the everyday work around a project. Start with the job you want to do, then choose a tool. Some releases are full desktop apps; others are previews or source editions. Their release pages explain what is ready today.</p></section><div class="feature-columns"><section><span class="eyebrow">01 / BUILD</span><h2>Create a game</h2><p>Explore genre-focused makers for platformers, top-down adventures, fighters, racers, strategy, and more.</p>'+links(['platform-maker','top-down-maker','fighter-maker','racing-maker'])+'<a href="#makers">See the maker collection ↓</a></section><section><span class="eyebrow">02 / EXPRESS</span><h2>Art, sound & motion</h2><p>Draw and shape visual work, develop musical ideas, or explore video and animation tools.</p>'+links(['the-adventures-of-moly-bart-skid-crystal-run','yheti-studio','yflux','soloist-forge'])+'</section><section><span class="eyebrow">03 / FINISH</span><h2>Prepare & organize</h2><p>Prepare game assets, organize your creative reserve, and keep a home for projects and tools.</p>'+links(['yeti-forge','yault','y-hub','yeti-browser'])+'</section></div><section class="wide"><h2>A closer look at the tools</h2><div class="spotlight-grid">'+''.join(card(p,catalog) for p in products if p['section']=='tools')+'</div></section><section class="wide" id="makers"><h2>The maker collection</h2><p>Choose a genre and explore the current editor, demo, export options, and requirements on its official release page.</p><div class="maker-links">'+''.join(f'<a href="{c["url"]}">{E(c["title"])} ↗</a>' for c in makers)+'</div></section><section class="callout"><h2>Build out your workspace</h2><p><a href="/assets/">Game assets</a> · <a href="/os/">PlaySpace & Prismatic Linux</a> · <a href="/desktop-buddy/">Desktop Buddy</a> · <a href="/tools/">Every tool & app</a></p><p>A Drunk Yeti account connects supported apps and services. Product pages explain which account, cosmetic, and Frostpass features each build currently supports.</p></section>'
    publish('create','Tools for your next idea','Explore Drunk Yeti game makers, art and animation apps, music tools, asset preparation software, and creative workspaces.',create)

    comic=lookup['moly-bart-skid']
    worlds='<div class="project-lead"><div><span class="eyebrow">ORIGINAL STORIES</span><h2>Moly, Bart & Skid</h2><p>A missing spring. An ancient machine. Three friends whose different abilities bring a world into reach. Begin with <em>The Heart Under the Mountain</em>.</p><a class="button ink" href="/comics/moly-bart-skid/">Meet the trio →</a></div><img src="'+asset(catalog[comic['catalogSlug']])+'" alt="The Heart Under the Mountain cover" width="630" height="500"></div><div class="feature-columns"><section><h2>Music beyond the game</h2><p>Stay in a world a little longer through its soundtrack. Explore music releases from across the studio.</p><a href="/soundtracks/">Browse soundtracks →</a></section><section><h2>See it in motion</h2><p>Watch gameplay, studio experiments, and project videos on our official channel.</p><a href="/#watch">Watch the studio →</a></section><section><h2>Take the Yeti with you</h2><p>Explore original studio designs on available clothing, prints, stickers, and other products.</p><a href="/#merch">Discover official merch →</a></section></div><section class="callout"><h2>One studio. Many ways into a world.</h2><p>Games, illustrated stories, sound, and playful software share a creative home at Drunk Yeti. Meet the projects on their own terms, whether you have a few minutes to read, a game to play, or an idea to make.</p><p><a href="/comics/">All comics</a> · <a href="/play/">Explore games</a> · <a href="/about/">Meet the studio</a></p></section>'
    publish('worlds','Original worlds, beyond the screen','Explore Drunk Yeti comics, original characters, soundtracks, gameplay videos, and official merchandise.',worlds)

    about='''<section><h2>Design with a technical mind.</h2><p>Drunk Yeti is an independent game, software, and multimedia studio. Our team brings playful ideas into games, creative tools, illustrated stories, and music.</p><p>Our mission is to make memorable worlds to explore and useful tools that help other people build their own. The work moves between art and engineering: a character can inspire a game, a production problem can become a tool, and a soundtrack can give a world another life.</p></section><div class="feature-columns"><section><h2>Play with personality</h2><p>Original characters, expressive worlds, and room for experimentation give our games their identity.</p><a href="/play/">Explore games →</a></section><section><h2>Make room for creators</h2><p>Our software covers game creation, art, music, asset preparation, and project organization.</p><a href="/create/">Explore creative tools →</a></section><section><h2>Build beyond one medium</h2><p>Comics, soundtracks, video, and desktop companions extend the studio beyond a single kind of release.</p><a href="/worlds/">Explore worlds & media →</a></section></div><section class="callout"><h2>A connected creative home</h2><p>Your studio account is a home for supported services, social connections, Shards, and eligible Frostpass benefits. Desktop Buddy brings a little of that personality onto your computer. Integrations depend on the product and build; each release explains what is supported.</p><p><a href="/account/">Your account</a> · <a href="/desktop-buddy/">Meet Desktop Buddy</a> · <a href="/help/">Account support</a></p></section><section><h2>Follow the work</h2><p>Find official releases on <a href="https://drunkyeti.itch.io">itch.io</a> and <a href="https://store.steampowered.com/curator/45875400">Steam</a>, and gameplay on <a href="https://www.youtube.com/channel/UCT4krkccy2JVXcyzIQi8ZPw/">YouTube</a>. Follow <a href="https://www.instagram.com/drunkyetistudios/">Instagram</a> for more from the studio.</p><h2>Start a conversation</h2><p>For support, press, or collaboration inquiries, contact <a href="mailto:support@drunkyetistudio.com">support@drunkyetistudio.com</a>. Include the project and the purpose of your message so we can route it appropriately.</p><p><a href="/press/">Studio facts, brand assets & press contact →</a></p></section>'''
    publish('about','Meet Drunk Yeti Studio','Meet Drunk Yeti Studio: original games, creative software, comics, music, and worlds by Michael Lambert Jr, also known as 3ichael 7ambert.',about,intro='Meet the team behind Drunk Yeti Studio: original games, creative software, comics, music, and worlds shaped by art, engineering, and storytelling.')

    press='''<section><h2>The studio, in a few words</h2><p>Drunk Yeti Studio is an independent game, software, and multimedia studio. The team’s work spans original games, creative applications, illustrated stories, music, and the Drunk Yeti Desktop Buddy. The studio’s guiding idea is “Design with a Technical Mind.”</p><p><a href="studio-facts.txt" download>Download studio facts & boilerplate</a></p><h2>Brand assets</h2><p><a href="/assets/logo.png" download>Download the Drunk Yeti logo (PNG)</a> · <a href="/assets/social-preview-v1.png" download>Download the studio social image (PNG)</a></p><p>Use these assets to identify Drunk Yeti in editorial coverage. Keep the proportions and colors intact. Product covers are promotional artwork; use each official release gallery for project imagery and version context. Contact us for other uses or additional materials.</p></section><section class="callout"><h2>Press, creators & collaborators</h2><p>Email <a href="mailto:support@drunkyetistudio.com?subject=Press%20or%20collaboration%20inquiry">support@drunkyetistudio.com</a> with your publication or channel, the project you are covering, and your deadline. For a collaboration, include the scope and the best way to reach you.</p><p>For a game, app, account, or purchase problem, start with <a href="/help/">Help & support</a>.</p></section><section><h2>Explore the work</h2><p><a href="/play/">Games</a> · <a href="/create/">Software</a> · <a href="/worlds/">Comics & music</a> · <a href="/desktop-buddy/">Desktop Buddy</a></p><p>Release pages are the source for current editions, prices, supported platforms, and download availability. Please distinguish a preview or demo from a full edition when covering a project.</p></section>'''
    publish('press','Press & contact','Find Drunk Yeti Studio facts, official brand assets, product information, and contact details for press and collaboration inquiries.',press)
    write('press/studio-facts.txt','Drunk Yeti Studio\nIndependent games, creative software, and multimedia.\n\n'+html.unescape(re.sub('<[^>]+>','',about.split('<div class="feature-columns">')[0].replace('</p>', '\n\n').replace('</h2>', '\n\n'))).strip()+'\n\nOfficial website: https://www.drunkyetistudio.com\nReleases: https://drunkyeti.itch.io\nSteam: https://store.steampowered.com/curator/45875400\nContact: support@drunkyetistudio.com\n')

    home=R/'index.html'
    fragment='<section class="section browser-section" id="play-now"><div class="section-heading"><div><div class="eyebrow">STRAIGHT INTO THE ACTION</div><h2>Open a tab.<br><em>Enter a world.</em></h2></div><a class="text-link" href="/play/">Find your next game →</a></div>'+browser_cards(products,catalog)+'</section><section class="section highlights" id="featured"><div class="section-heading"><div><div class="eyebrow">FEATURED PROJECTS</div><h2>A few places<br><em>to begin.</em></h2></div><p>Original games, useful tools, and stories with somewhere to go.</p></div><div class="spotlight-grid">'+''.join(card(lookup[s],catalog) for s in ['snowlight','ar3na','yeti-forge','moly-bart-skid'])+'</div></section>'
    text=home.read_text();text,n=re.subn(r'<!-- STUDIO_FEATURES_START -->.*?<!-- STUDIO_FEATURES_END -->','<!-- STUDIO_FEATURES_START -->\n'+fragment+'\n<!-- STUDIO_FEATURES_END -->',text,flags=re.S)
    if n!=1:raise ValueError('Homepage requires exactly one editorial feature block')
    home.write_text(text)
    return urls
